-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (10759, 42, 'Einkommensteuertarif und Freibeträge automatisch an die Inflation anpassen (Bund)', 'Setzt direkt an der kalten Progression an; Schweiz, USA, Kanada, Belgien u. a. indexieren automatisch, Simulationen zeigen weitgehenden Ausgleich. Dagegen: Einnahmeausfall gegenüber Status quo und weniger Budgetspielraum; einfaches Bundesgesetz mit Bundesratszustimmung.', 'belegt', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2016/heft/10/beitrag/moeglichkeiten-zur-kompensation-der-kalten-progression-wirkung-in-oesterreich.html', 'bund', null, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Ein Inflationsausgleich im Tarif lässt Mehreinnahmen entfallen: Die 2025 neu entstehende kalte Progression betrug rund 7,9 Mrd. Euro, davon rund 3,3 Mrd. Euro bei den Ländern.","quelle_url":"https://dserver.bundestag.de/btd/20/135/2013560.pdf","belegstufe":"A"}]'::jsonb),
  (10760, 42, 'Grundfreibetrag der Einkommensteuer stark anheben (auf etwa 15.000 bis 17.000 Euro) (Bund)', 'Entlastet alle Steuerpflichtigen spürbar und gleicht aufgelaufene kalte Progression mehr als aus. Dagegen: einmaliger Schritt ohne dauerhafte Anpassung und Ausfälle in zweistelliger Milliardenhöhe ohne geklärte Gegenfinanzierung.', 'belegt', null, 'bund', null, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Eine Anhebung des Grundfreibetrags um 216 Euro mindert die Steuereinnahmen laut Gesetzentwurf um rund 1,9 Mrd. Euro im Jahr; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dserver.bundestag.de/brd/2026/0507-26.pdf","belegstufe":"A"}]'::jsonb),
  (10761, 42, 'Einkommensteuertarif abflachen und Spitzensteuersatz später greifen lassen, ohne Gegenfinanzierung (Bund)', 'Mildert den steilen Progressionsverlauf bei mittleren Einkommen, an dem die kalte Progression besonders wirkt. Dagegen: einmalige Änderung ohne Indexierung, Entlastung absolut v. a. bei höheren Einkommen, hohe Ausfälle ohne Finanzierung.', 'gemischt', null, 'bund', null, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das gesamte Einkommensteuerreformgesetz 2027 mindert die Steuereinnahmen um rund 5,6 Mrd. Euro im Jahr 2028; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dserver.bundestag.de/brd/2026/0507-26.pdf","belegstufe":"A"}]'::jsonb),
  (10762, 42, 'Einkommensteuertarif umbauen: untere und mittlere Einkommen entlasten, hohe stärker belasten (Bund)', 'Senkt die Belastung der Mehrheit der Beschäftigten und ist teilweise gegenfinanziert. Dagegen: keine dauerhafte Inflationsanpassung, Ausweichreaktionen hoher Einkommen mindern die Gegenfinanzierung.', 'gemischt', null, 'bund', null, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das gesamte Einkommensteuerreformgesetz 2027, mit höherem Reichensteuersatz gegenfinanziert, mindert die Einnahmen um rund 5,6 Mrd. Euro im Jahr 2028; nicht die Kosten dieses Wegs.","quelle_url":"https://dserver.bundestag.de/brd/2026/0507-26.pdf","belegstufe":"A"}]'::jsonb),
  (10763, 42, 'Schuldenbremse einhalten, keine Lockerung (Bund)', 'Fiskalregeln gehen laut IWF mit niedrigeren Defiziten einher, besonders bei verbindlicher Ausgestaltung. Dagegen: kausaler Effekt umstritten, Regeln drücken oft Investitionen; geltendes Recht, daher leicht umsetzbar.', 'gemischt', 'https://www.imf.org/-/media/files/publications/sdn/2018/sdn1804-on-second-generation-fiscal-rules.pdf.md', 'bund', null, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Zum Vergleich: Im Finanzplan sinkt die Kreditaufnahme innerhalb der Schuldenregel von 40,4 Mrd. Euro 2026 auf 15,6 Mrd. Euro 2030; das sind nicht die Einsparungen dieses Wegs.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205072","belegstufe":"A"}]'::jsonb),
  (10764, 42, 'Schuldenbremse lockern oder abschaffen, um Investitionen über Kredite zu finanzieren (Bund)', 'Kann Investitionsstau abbauen und Wachstum stützen; IWF verweist auf Investitionsverdrängung durch starre Regeln. Dagegen: erhöht Defizit und Zinslast unmittelbar; erfordert Grundgesetzänderung mit Zweidrittelmehrheit, EU-Regeln gelten weiter.', 'gemischt', 'https://www.imf.org/-/media/files/publications/sdn/2018/sdn1804-on-second-generation-fiscal-rules.pdf.md', 'bund', null, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der Finanzplan sieht Zinsausgaben des Bundes von rund 41,9 Mrd. Euro 2027 und 80,7 Mrd. Euro 2030 vor; das sind nicht allein die Kosten dieses Wegs.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205072","belegstufe":"A"},{"bereich":"umwelt","richtung":"vorteil","text":"Zum Vergleich: Das Sondervermögen mit bis zu 500 Mrd. Euro Kredit führt dem Klima- und Transformationsfonds 100 Mrd. Euro zu; das sind nicht allein die Folgen dieses Wegs.","quelle_url":"https://dserver.bundestag.de/btd/21/007/2100779.pdf","belegstufe":"A"}]'::jsonb),
  (10765, 42, 'Subventionen und Ausgaben systematisch überprüfen und abbauen (Bund)', 'Finanzhilfen und Steuervergünstigungen des Bundes umfassen dreistellige Milliardenbeträge, Abbau senkt das Defizit spürbar. Dagegen: Einsparziele bleiben oft unbestimmt, viele Posten sind politisch und rechtlich gebunden.', 'gemischt', null, 'bund', null, true, 'blind', '[{"bereich":"umwelt","richtung":"vorteil","text":"Zum Vergleich: Die umweltschädlichen Subventionen beliefen sich 2018 auf über 65 Mrd. Euro; das ist nicht der Betrag, den dieser Weg abbaut.","quelle_url":"https://www.umweltbundesamt.de/daten/umwelt-wirtschaft/umweltschaedliche-subventionen-in-deutschland","belegstufe":"A"}]'::jsonb),
  (10766, 42, 'Bundesverwaltung verkleinern (Stellenabbau, Digitalisierung) (Bund)', 'Senkt Personal- und Verwaltungskosten auf längere Sicht. Dagegen: Personalausgaben sind nur ein kleiner Teil des Bundeshaushalts, Digitalisierung kostet zunächst; Einsparungen kaum untersucht.', 'offen', null, 'bund', null, true, 'blind', '[]'::jsonb),
  (10767, 42, 'Steuerhinterziehung und Steuerbetrug stärker verfolgen, Steuerverwaltung personell stärken (Bund)', 'Betriebsprüfer erzielen im Schnitt rund 1 Mio. Euro Mehrergebnis je Jahr, mehr Personal erhöht die Einnahmen. Dagegen: Finanzämter sind Ländersache, Fachkräfte fehlen; der Bund kann nur über Gesetze, Bundesbehörden und Vereinbarungen beitragen.', 'belegt', 'https://www.zdfheute.de/wirtschaft/kampf-gegen-steuerhinterziehung-finanzamt-100.html', 'bund', null, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Zum Vergleich: Betriebsprüfungen der Länder stellten 2023 steuerliche Mehrergebnisse von rund 13,2 Mrd. Euro fest; das sind nicht die Erträge zusätzlicher Prüfer.","quelle_url":"https://dserver.bundestag.de/btd/20/112/2011267.pdf","belegstufe":"A"}]'::jsonb),
  (10768, 42, 'Vermögensteuer wieder erheben (Bund)', 'Erhöht den Anteil vermögensbezogener Steuern; DIW schätzt je nach Ausgestaltung zweistellige Milliardenbeträge. Dagegen: Ausweichreaktionen, Bewertungsaufwand und Verfassungsvorgaben zur Bewertung; Aufkommen fließt den Ländern zu.', 'gemischt', 'https://www.diw.de/de/diw_01.c.1002952.de/nachrichten/es_gibt_bessere_wege__vermoegen_zu_besteuern.html', 'bund', null, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Das DIW schätzte 2016 für eine wieder erhobene Vermögensteuer auch bei hohen Freibeträgen ein Aufkommen von 10 bis 20 Mrd. Euro im Jahr.","quelle_url":"https://www.diw.de/de/diw_01.c.525353.de/publikationen/wochenberichte/2016_04/hohes_aufkommenspotential_bei_wiedererhebung_der_vermoegensteuer.html","belegstufe":"B"}]'::jsonb),
  (10769, 42, 'Verschonung großer Betriebsvermögen bei der Erbschaftsteuer begrenzen oder Mindeststeuer einführen (Bund)', 'Große Betriebsvermögen werden weitgehend steuerfrei übertragen, Schätzungen nennen Ausfälle in Milliardenhöhe; Stundung kann Liquiditätsprobleme mildern. Dagegen: Unternehmensverbände warnen vor Investitionsfolgen, Ausweichgestaltungen möglich.', 'gemischt', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2016/heft/6/beitrag/die-demontage-der-erbschaftsteuer.html', 'bund', null, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Bei großen Betriebsvermögen wurden 2025 im Rahmen der Verschonungsbedarfsprüfung Steuern von 3,7 Mrd. Euro erlassen; eine Begrenzung der Verschonung betrifft solche Beträge.","quelle_url":"https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/08/PD26_306_736.html","belegstufe":"A"}]'::jsonb),
  (10770, 42, 'Freibeträge der Erbschaft- und Schenkungsteuer erhöhen oder an die Inflation koppeln (Bund)', 'Setzt an der Erbschaftsteuer an, senkt aber deren Aufkommen und verstärkt damit das Übergewicht von Lohn- und Umsatzsteuer. Für einzelne Erben (Eigenheim) entlastend; rechtlich einfach umsetzbar.', 'belegt', null, 'bund', null, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die festgesetzte Erbschaftsteuer lag 2025 bei 13,3 Mrd. Euro; das sind nicht die Mindereinnahmen dieses Wegs, zeigt aber das Aufkommen, an dem er ansetzt.","quelle_url":"https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/08/PD26_306_736.html","belegstufe":"A"}]'::jsonb),
  (10771, 42, 'Nationale Finanztransaktionssteuer einführen (Bund)', 'Besteuert bisher steuerfreie Kapitaltransaktionen; Frankreich und Italien erheben sie. Dagegen: dortige Einnahmen blieben unter den Prognosen, Handel weicht aus; national einführbar, Bemessungsgrundlage strittig.', 'gemischt', 'https://articlegateway.com/index.php/JAF/article/view/6562', 'bund', null, true, 'blind', '[{"bereich":"wirtschaft","richtung":"gemischt","text":"Die Wissenschaftlichen Dienste verweisen auf Erfahrungen in Frankreich und Italien: Handelsvolumen kurz- bis mittelfristig 10 bis 30 Prozent niedriger, aber nur begrenzte Effekte auf die Liquidität.","quelle_url":"https://www.bundestag.de/resource/blob/1100514/WD-4-022-25.pdf","belegstufe":"B"}]'::jsonb)
