insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (10772, 42, 11, null, 'Einkommensteuertarif schrittweise senken, Grundfreibetrag erhöhen, Grenze für den Spitzensteuersatz anheben', '{4201}', 10761, 2, 1, null, 'Mildert den steilen Progressionsverlauf bei mittleren Einkommen, an dem die kalte Progression besonders wirkt. Dagegen: einmalige Änderung ohne Indexierung, Entlastung absolut v. a. bei höheren Einkommen, hohe Ausfälle ohne Finanzierung.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=14', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das gesamte Einkommensteuerreformgesetz 2027 mindert die Steuereinnahmen um rund 5,6 Mrd. Euro im Jahr 2028; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dserver.bundestag.de/brd/2026/0507-26.pdf","belegstufe":"A"}]'::jsonb),
  (10773, 42, 11, null, 'Einkommensteuertarif regelmäßig an die Inflation anpassen, um die kalte Progression auszugleichen', '{4201}', 10759, 3, 3, null, 'Setzt direkt an der kalten Progression an; Schweiz, USA, Kanada, Belgien u. a. indexieren automatisch, Simulationen zeigen weitgehenden Ausgleich. Dagegen: Einnahmeausfall gegenüber Status quo und weniger Budgetspielraum; einfaches Bundesgesetz mit Bundesratszustimmung.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=14', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2016/heft/10/beitrag/moeglichkeiten-zur-kompensation-der-kalten-progression-wirkung-in-oesterreich.html', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Ein Inflationsausgleich im Tarif lässt Mehreinnahmen entfallen: Die 2025 neu entstehende kalte Progression betrug rund 7,9 Mrd. Euro, davon rund 3,3 Mrd. Euro bei den Ländern.","quelle_url":"https://dserver.bundestag.de/btd/20/135/2013560.pdf","belegstufe":"A"}]'::jsonb),
  (10774, 42, 11, null, 'Freibeträge bei der Erbschaftsteuer deutlich erhöhen', '{4203}', 10770, 0, 3, null, 'Setzt an der Erbschaftsteuer an, senkt aber deren Aufkommen und verstärkt damit das Übergewicht von Lohn- und Umsatzsteuer. Für einzelne Erben (Eigenheim) entlastend; rechtlich einfach umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=34', null, 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die festgesetzte Erbschaftsteuer lag 2025 bei 13,3 Mrd. Euro; das sind nicht die Mindereinnahmen dieses Wegs, zeigt aber das Aufkommen, an dem er ansetzt.","quelle_url":"https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/08/PD26_306_736.html","belegstufe":"A"}]'::jsonb),
  (10775, 42, 11, null, 'Kassensturz beim Bund, alle Ausgaben und Subventionen hinterfragen, Ausgaben die ihr Ziel verfehlen entfallen lassen', '{4202}', 10765, 2, 2, null, 'Finanzhilfen und Steuervergünstigungen des Bundes umfassen dreistellige Milliardenbeträge, Abbau senkt das Defizit spürbar. Dagegen: Einsparziele bleiben oft unbestimmt, viele Posten sind politisch und rechtlich gebunden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=77', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"umwelt","richtung":"vorteil","text":"Zum Vergleich: Die umweltschädlichen Subventionen beliefen sich 2018 auf über 65 Mrd. Euro; das ist nicht der Betrag, den dieser Weg abbaut.","quelle_url":"https://www.umweltbundesamt.de/daten/umwelt-wirtschaft/umweltschaedliche-subventionen-in-deutschland","belegstufe":"A"}]'::jsonb),
  (10776, 42, 11, null, 'Maastricht-Kriterien (Schuldenstand, Defizit) verbindlich halten, Verstöße über automatisiertes Defizitverfahren sanktionieren', '{4202}', null, 1, 1, null, 'Verbindliche EU-Defizitregeln können Haushaltsdisziplin stärken. Dagegen: Regeln gelten bereits, ein automatisiertes Verfahren erfordert EU-Beschlüsse, die Deutschland nicht allein treffen kann.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=78', null, 'gemischt', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10777, 42, 12, null, 'Einkommensteuertarif so entlasten, dass die große Mehrheit der Steuerpflichtigen profitiert; Spitzeneinkommen und -vermögen stärker beteiligen.', '{4201}', 10762, 2, 2, null, 'Senkt die Belastung der Mehrheit der Beschäftigten und ist teilweise gegenfinanziert. Dagegen: keine dauerhafte Inflationsanpassung, Ausweichreaktionen hoher Einkommen mindern die Gegenfinanzierung.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=23', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das gesamte Einkommensteuerreformgesetz 2027, mit höherem Reichensteuersatz gegenfinanziert, mindert die Einnahmen um rund 5,6 Mrd. Euro im Jahr 2028; nicht die Kosten dieses Wegs.","quelle_url":"https://dserver.bundestag.de/brd/2026/0507-26.pdf","belegstufe":"A"}]'::jsonb),
  (10778, 42, 12, null, 'Schuldenregel im Grundgesetz reformieren, damit Investitionen nicht behindert werden; mehr Kreditspielraum.', '{4202}', 10764, 1, 1, null, 'Kann Investitionsstau abbauen und Wachstum stützen; IWF verweist auf Investitionsverdrängung durch starre Regeln. Dagegen: erhöht Defizit und Zinslast unmittelbar; erfordert Grundgesetzänderung mit Zweidrittelmehrheit, EU-Regeln gelten weiter.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=17', 'https://www.imf.org/-/media/files/publications/sdn/2018/sdn1804-on-second-generation-fiscal-rules.pdf.md', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der Finanzplan sieht Zinsausgaben des Bundes von rund 41,9 Mrd. Euro 2027 und 80,7 Mrd. Euro 2030 vor; das sind nicht allein die Kosten dieses Wegs.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205072","belegstufe":"A"},{"bereich":"umwelt","richtung":"vorteil","text":"Zum Vergleich: Das Sondervermögen mit bis zu 500 Mrd. Euro Kredit führt dem Klima- und Transformationsfonds 100 Mrd. Euro zu; das sind nicht allein die Folgen dieses Wegs.","quelle_url":"https://dserver.bundestag.de/btd/21/007/2100779.pdf","belegstufe":"A"}]'::jsonb),
  (10779, 42, 12, null, 'Vermögensteuer für sehr hohe Vermögen wieder einführen und so Einnahmen erhöhen.', '{4203}', 10768, 2, 2, null, 'Erhöht den Anteil vermögensbezogener Steuern; DIW schätzt je nach Ausgestaltung zweistellige Milliardenbeträge. Dagegen: Ausweichreaktionen, Bewertungsaufwand und Verfassungsvorgaben zur Bewertung; Aufkommen fließt den Ländern zu.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=19', 'https://www.diw.de/de/diw_01.c.1002952.de/nachrichten/es_gibt_bessere_wege__vermoegen_zu_besteuern.html', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Das DIW schätzte 2016 für eine wieder erhobene Vermögensteuer auch bei hohen Freibeträgen ein Aufkommen von 10 bis 20 Mrd. Euro im Jahr.","quelle_url":"https://www.diw.de/de/diw_01.c.525353.de/publikationen/wochenberichte/2016_04/hohes_aufkommenspotential_bei_wiedererhebung_der_vermoegensteuer.html","belegstufe":"B"}]'::jsonb),
  (10780, 42, 12, null, 'Mindestbesteuerung für große Betriebsvermögen bei Erbschaften und Schenkungen einführen.', '{4203}', 10769, 2, 3, null, 'Große Betriebsvermögen werden weitgehend steuerfrei übertragen, Schätzungen nennen Ausfälle in Milliardenhöhe; Stundung kann Liquiditätsprobleme mildern. Dagegen: Unternehmensverbände warnen vor Investitionsfolgen, Ausweichgestaltungen möglich.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=19', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2016/heft/6/beitrag/die-demontage-der-erbschaftsteuer.html', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Bei großen Betriebsvermögen wurden 2025 im Rahmen der Verschonungsbedarfsprüfung Steuern von 3,7 Mrd. Euro erlassen; eine Begrenzung der Verschonung betrifft solche Beträge.","quelle_url":"https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/08/PD26_306_736.html","belegstufe":"A"}]'::jsonb),
  (10781, 42, 12, null, 'Finanztransaktionssteuer einführen, weil Finanztransaktionen bisher nicht besteuert werden.', '{4203}', 10771, 1, 2, null, 'Besteuert bisher steuerfreie Kapitaltransaktionen; Frankreich und Italien erheben sie. Dagegen: dortige Einnahmen blieben unter den Prognosen, Handel weicht aus; national einführbar, Bemessungsgrundlage strittig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=19', 'https://articlegateway.com/index.php/JAF/article/view/6562', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"wirtschaft","richtung":"gemischt","text":"Die Wissenschaftlichen Dienste verweisen auf Erfahrungen in Frankreich und Italien: Handelsvolumen kurz- bis mittelfristig 10 bis 30 Prozent niedriger, aber nur begrenzte Effekte auf die Liquidität.","quelle_url":"https://www.bundestag.de/resource/blob/1100514/WD-4-022-25.pdf","belegstufe":"B"}]'::jsonb),
  (10782, 42, 13, null, 'Arbeitnehmerpauschbetrag in der Einkommensteuer auf mindestens 1.500 Euro anheben.', '{4201}', null, 1, 3, null, 'Der Pauschbetrag ist nicht indexiert; eine Anhebung gleicht Inflation für Beschäftigte teilweise aus und vereinfacht. Dagegen: einmaliger Schritt, Wirkung je Person gering.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=74', null, 'offen', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Eine Anhebung des Arbeitnehmer-Pauschbetrags auf 1.430 Euro mindert die Steuereinnahmen laut Gesetzentwurf um rund 1,1 Mrd. Euro im Jahr; nicht die Kosten dieses Wegs.","quelle_url":"https://dserver.bundestag.de/brd/2026/0507-26.pdf","belegstufe":"A"},{"bereich":"aufwand","richtung":"vorteil","text":"Bei einer Anhebung auf 1.430 Euro rechnet die Bundesregierung mit 1,3 Mio. Beschäftigten, die keine Anlage N mehr ausfüllen, und mit rund 108.000 Stunden weniger Aufwand im Jahr.","quelle_url":"https://dserver.bundestag.de/brd/2026/0507-26.pdf","belegstufe":"A"}]'::jsonb),
  (10783, 42, 13, null, 'Schuldenbremse reformieren: Kredite in dem Umfang zulassen, wie der Staat investiert.', '{4202}', 10764, 1, 1, null, 'Kann Investitionsstau abbauen und Wachstum stützen; IWF verweist auf Investitionsverdrängung durch starre Regeln. Dagegen: erhöht Defizit und Zinslast unmittelbar; erfordert Grundgesetzänderung mit Zweidrittelmehrheit, EU-Regeln gelten weiter.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=36', 'https://www.imf.org/-/media/files/publications/sdn/2018/sdn1804-on-second-generation-fiscal-rules.pdf.md', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der Finanzplan sieht Zinsausgaben des Bundes von rund 41,9 Mrd. Euro 2027 und 80,7 Mrd. Euro 2030 vor; das sind nicht allein die Kosten dieses Wegs.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205072","belegstufe":"A"},{"bereich":"umwelt","richtung":"vorteil","text":"Zum Vergleich: Das Sondervermögen mit bis zu 500 Mrd. Euro Kredit führt dem Klima- und Transformationsfonds 100 Mrd. Euro zu; das sind nicht allein die Folgen dieses Wegs.","quelle_url":"https://dserver.bundestag.de/btd/21/007/2100779.pdf","belegstufe":"A"}]'::jsonb),
  (10784, 42, 13, null, 'Steuerschlupflöcher schließen, um den Haushalt zu entlasten.', '{4202}', null, 1, 2, null, 'Schließen von Steuerschlupflöchern kann Mehreinnahmen bringen. Dagegen: ohne Benennung konkreter Regelungen bleiben Umfang und Wirkung unbestimmt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=37', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10785, 42, 13, null, 'Klima- und umweltschädliche Subventionen abbauen.', '{4202}', 10765, 2, 2, null, 'Finanzhilfen und Steuervergünstigungen des Bundes umfassen dreistellige Milliardenbeträge, Abbau senkt das Defizit spürbar. Dagegen: Einsparziele bleiben oft unbestimmt, viele Posten sind politisch und rechtlich gebunden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=37', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"umwelt","richtung":"vorteil","text":"Zum Vergleich: Die umweltschädlichen Subventionen beliefen sich 2018 auf über 65 Mrd. Euro; das ist nicht der Betrag, den dieser Weg abbaut.","quelle_url":"https://www.umweltbundesamt.de/daten/umwelt-wirtschaft/umweltschaedliche-subventionen-in-deutschland","belegstufe":"A"}]'::jsonb),
  (10786, 42, 13, null, 'Verwaltung durch weitere Digitalisierung verschlanken, um den Haushalt zu entlasten.', '{4202}', 10766, 1, 2, null, 'Senkt Personal- und Verwaltungskosten auf längere Sicht. Dagegen: Personalausgaben sind nur ein kleiner Teil des Bundeshaushalts, Digitalisierung kostet zunächst; Einsparungen kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=37', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10787, 42, 13, null, 'Erbschaftsteuer reformieren mit personenbezogenem Lebensfreibetrag und Ausnahmen für sehr große Erbschaften streichen.', '{4203}', 10769, 2, 3, null, 'Große Betriebsvermögen werden weitgehend steuerfrei übertragen, Schätzungen nennen Ausfälle in Milliardenhöhe; Stundung kann Liquiditätsprobleme mildern. Dagegen: Unternehmensverbände warnen vor Investitionsfolgen, Ausweichgestaltungen möglich.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=73', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2016/heft/6/beitrag/die-demontage-der-erbschaftsteuer.html', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Bei großen Betriebsvermögen wurden 2025 im Rahmen der Verschonungsbedarfsprüfung Steuern von 3,7 Mrd. Euro erlassen; eine Begrenzung der Verschonung betrifft solche Beträge.","quelle_url":"https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/08/PD26_306_736.html","belegstufe":"A"}]'::jsonb),
  (10788, 42, 14, null, 'Einkommensteuer-Freibeträge und Eckwerte automatisch an die Preisentwicklung anpassen', '{4201}', 10759, 3, 3, null, 'Setzt direkt an der kalten Progression an; Schweiz, USA, Kanada, Belgien u. a. indexieren automatisch, Simulationen zeigen weitgehenden Ausgleich. Dagegen: Einnahmeausfall gegenüber Status quo und weniger Budgetspielraum; einfaches Bundesgesetz mit Bundesratszustimmung.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=14', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2016/heft/10/beitrag/moeglichkeiten-zur-kompensation-der-kalten-progression-wirkung-in-oesterreich.html', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Ein Inflationsausgleich im Tarif lässt Mehreinnahmen entfallen: Die 2025 neu entstehende kalte Progression betrug rund 7,9 Mrd. Euro, davon rund 3,3 Mrd. Euro bei den Ländern.","quelle_url":"https://dserver.bundestag.de/btd/20/135/2013560.pdf","belegstufe":"A"}]'::jsonb),
  (10789, 42, 14, null, 'Grundfreibetrag schrittweise um mindestens 1.000 Euro anheben', '{4201}', null, 1, 3, null, 'Höherer Grundfreibetrag entlastet alle Steuerpflichtigen und gleicht einen Teil der kalten Progression aus. Dagegen: einmaliger, mäßiger Schritt ohne dauerhafte Anpassung.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=14', null, 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Eine Anhebung des Grundfreibetrags um 216 Euro mindert die Steuereinnahmen laut Gesetzentwurf um rund 1,9 Mrd. Euro im Jahr; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dserver.bundestag.de/brd/2026/0507-26.pdf","belegstufe":"A"}]'::jsonb),
  (10790, 42, 14, null, 'Einkommensteuertarif als linear-progressiver Chancentarif, der den Mittelstandsbauch beseitigt', '{4201}', 10761, 2, 1, null, 'Mildert den steilen Progressionsverlauf bei mittleren Einkommen, an dem die kalte Progression besonders wirkt. Dagegen: einmalige Änderung ohne Indexierung, Entlastung absolut v. a. bei höheren Einkommen, hohe Ausfälle ohne Finanzierung.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=14', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das gesamte Einkommensteuerreformgesetz 2027 mindert die Steuereinnahmen um rund 5,6 Mrd. Euro im Jahr 2028; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dserver.bundestag.de/brd/2026/0507-26.pdf","belegstufe":"A"}]'::jsonb),
  (10791, 42, 14, null, 'Spitzensteuersatz erst bei höherem Einkommen greifen lassen (Bindung an die Beitragsbemessungsgrenze)', '{4201}', 10761, 2, 1, null, 'Mildert den steilen Progressionsverlauf bei mittleren Einkommen, an dem die kalte Progression besonders wirkt. Dagegen: einmalige Änderung ohne Indexierung, Entlastung absolut v. a. bei höheren Einkommen, hohe Ausfälle ohne Finanzierung.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=14', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das gesamte Einkommensteuerreformgesetz 2027 mindert die Steuereinnahmen um rund 5,6 Mrd. Euro im Jahr 2028; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dserver.bundestag.de/brd/2026/0507-26.pdf","belegstufe":"A"}]'::jsonb),
  (10792, 42, 14, null, 'Schuldenbremse im Grundgesetz einhalten', '{4202}', 10763, 2, 3, null, 'Fiskalregeln gehen laut IWF mit niedrigeren Defiziten einher, besonders bei verbindlicher Ausgestaltung. Dagegen: kausaler Effekt umstritten, Regeln drücken oft Investitionen; geltendes Recht, daher leicht umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=35', 'https://www.imf.org/-/media/files/publications/sdn/2018/sdn1804-on-second-generation-fiscal-rules.pdf.md', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Zum Vergleich: Im Finanzplan sinkt die Kreditaufnahme innerhalb der Schuldenregel von 40,4 Mrd. Euro 2026 auf 15,6 Mrd. Euro 2030; das sind nicht die Einsparungen dieses Wegs.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205072","belegstufe":"A"}]'::jsonb),
  (10793, 42, 14, null, 'Subventionen zurückfahren, bis Finanzhilfen und Steuerermäßigungen zur Wertschöpfung passen', '{4202}', 10765, 2, 2, null, 'Finanzhilfen und Steuervergünstigungen des Bundes umfassen dreistellige Milliardenbeträge, Abbau senkt das Defizit spürbar. Dagegen: Einsparziele bleiben oft unbestimmt, viele Posten sind politisch und rechtlich gebunden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=36', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"umwelt","richtung":"vorteil","text":"Zum Vergleich: Die umweltschädlichen Subventionen beliefen sich 2018 auf über 65 Mrd. Euro; das ist nicht der Betrag, den dieser Weg abbaut.","quelle_url":"https://www.umweltbundesamt.de/daten/umwelt-wirtschaft/umweltschaedliche-subventionen-in-deutschland","belegstufe":"A"}]'::jsonb),
  (10794, 42, 14, null, 'Bundesausgaben stärker auf die originären Aufgaben des Bundes beschränken', '{4202}', null, 1, 3, null, 'Begrenzung auf Kernaufgaben kann Ausgaben senken. Dagegen: unbestimmt, welche Ausgaben entfallen; viele Bundesausgaben sind gesetzlich gebunden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=36', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10795, 42, 14, null, 'Stellenzahl in der Bundesverwaltung außerhalb der Sicherheitsbehörden deutlich reduzieren', '{4202}', 10766, 1, 2, null, 'Senkt Personal- und Verwaltungskosten auf längere Sicht. Dagegen: Personalausgaben sind nur ein kleiner Teil des Bundeshaushalts, Digitalisierung kostet zunächst; Einsparungen kaum untersucht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=37', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10796, 42, 14, null, 'Staatsbeteiligungen veräußern', '{4202}', null, 1, 2, null, 'Bringt einmalige Erlöse, die Schulden tilgen können. Dagegen: kein Beitrag zum strukturellen Defizit, entgangene Dividenden, Erlöse hängen vom Marktumfeld ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=36', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10797, 42, 14, null, 'Freibeträge der Erbschaft- und Schenkungsteuer automatisch an die Inflationsrate anpassen', '{4203}', 10770, 0, 3, null, 'Setzt an der Erbschaftsteuer an, senkt aber deren Aufkommen und verstärkt damit das Übergewicht von Lohn- und Umsatzsteuer. Für einzelne Erben (Eigenheim) entlastend; rechtlich einfach umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=15', null, 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die festgesetzte Erbschaftsteuer lag 2025 bei 13,3 Mrd. Euro; das sind nicht die Mindereinnahmen dieses Wegs, zeigt aber das Aufkommen, an dem er ansetzt.","quelle_url":"https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/08/PD26_306_736.html","belegstufe":"A"}]'::jsonb),
  (10798, 42, 15, null, 'Einkommensteuer-Freibeträge an die Inflation koppeln (indexieren)', '{4201}', 10759, 3, 3, null, 'Setzt direkt an der kalten Progression an; Schweiz, USA, Kanada, Belgien u. a. indexieren automatisch, Simulationen zeigen weitgehenden Ausgleich. Dagegen: Einnahmeausfall gegenüber Status quo und weniger Budgetspielraum; einfaches Bundesgesetz mit Bundesratszustimmung.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=59', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2016/heft/10/beitrag/moeglichkeiten-zur-kompensation-der-kalten-progression-wirkung-in-oesterreich.html', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Ein Inflationsausgleich im Tarif lässt Mehreinnahmen entfallen: Die 2025 neu entstehende kalte Progression betrug rund 7,9 Mrd. Euro, davon rund 3,3 Mrd. Euro bei den Ländern.","quelle_url":"https://dserver.bundestag.de/btd/20/135/2013560.pdf","belegstufe":"A"}]'::jsonb),
  (10799, 42, 15, null, 'Einkommensteuer-Grundfreibetrag auf 15.000 Euro erhöhen', '{4201}', 10760, 2, 1, null, 'Entlastet alle Steuerpflichtigen spürbar und gleicht aufgelaufene kalte Progression mehr als aus. Dagegen: einmaliger Schritt ohne dauerhafte Anpassung und Ausfälle in zweistelliger Milliardenhöhe ohne geklärte Gegenfinanzierung.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=59', null, 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Eine Anhebung des Grundfreibetrags um 216 Euro mindert die Steuereinnahmen laut Gesetzentwurf um rund 1,9 Mrd. Euro im Jahr; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dserver.bundestag.de/brd/2026/0507-26.pdf","belegstufe":"A"}]'::jsonb),
  (10800, 42, 15, null, 'Beitragszahlungen an die EU drastisch senken', '{4202}', null, 1, 1, null, 'Geringere EU-Beiträge würden den Bundeshaushalt entlasten. Dagegen: Finanzrahmen und Eigenmittel erfordern einstimmige EU-Beschlüsse, Rückflüsse aus EU-Programmen fielen ebenfalls weg.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=55', null, 'offen', '2026-10-22', false, true, 'blind', '[{"bereich":"wirtschaft","richtung":"nachteil","text":"Zum Vergleich: Aus dem EU-Haushalt erhielt Deutschland 2014 bis 2020 Direktzahlungen für die Landwirtschaft von rund 5 Mrd. Euro im Jahr; das sind nicht die Folgen geringerer Beiträge.","quelle_url":"https://www.bundestag.de/resource/blob/834626/3e7a070d5cce12c139b9686cecb5b658/WD-4-022-21-pdf.pdf","belegstufe":"A"}]'::jsonb),
  (10801, 42, 15, null, 'Schuldenbremse einhalten, keine Aufweichung', '{4202}', 10763, 2, 3, null, 'Fiskalregeln gehen laut IWF mit niedrigeren Defiziten einher, besonders bei verbindlicher Ausgestaltung. Dagegen: kausaler Effekt umstritten, Regeln drücken oft Investitionen; geltendes Recht, daher leicht umsetzbar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=55', 'https://www.imf.org/-/media/files/publications/sdn/2018/sdn1804-on-second-generation-fiscal-rules.pdf.md', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Zum Vergleich: Im Finanzplan sinkt die Kreditaufnahme innerhalb der Schuldenregel von 40,4 Mrd. Euro 2026 auf 15,6 Mrd. Euro 2030; das sind nicht die Einsparungen dieses Wegs.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205072","belegstufe":"A"}]'::jsonb),
  (10802, 42, 15, null, 'Erbschaftsteuer und Vermögensteuer abschaffen', '{4203}', null, 0, 1, null, 'Setzt an vermögensbezogenen Steuern an, senkt deren Anteil aber weiter und verstärkt das Übergewicht von Lohn- und Umsatzsteuer. Länder verlören ihr Erbschaftsteueraufkommen ohne geklärten Ausgleich.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=61', null, 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Die festgesetzte Erbschaftsteuer lag 2025 bei 13,3 Mrd. Euro; dieses Aufkommen entfiele bei einer Abschaffung.","quelle_url":"https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/08/PD26_306_736.html","belegstufe":"A"}]'::jsonb),
  (10803, 42, 16, null, 'Einkommen bis zu einer festen Grenze im Jahr steuerfrei stellen (Grundfreibetrag)', '{4201}', 10760, 2, 1, null, 'Entlastet alle Steuerpflichtigen spürbar und gleicht aufgelaufene kalte Progression mehr als aus. Dagegen: einmaliger Schritt ohne dauerhafte Anpassung und Ausfälle in zweistelliger Milliardenhöhe ohne geklärte Gegenfinanzierung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=11', null, 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Eine Anhebung des Grundfreibetrags um 216 Euro mindert die Steuereinnahmen laut Gesetzentwurf um rund 1,9 Mrd. Euro im Jahr; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dserver.bundestag.de/brd/2026/0507-26.pdf","belegstufe":"A"}]'::jsonb),
  (10804, 42, 16, null, 'Einkommensteuertarif umgestalten: niedrige Einkommen weniger, hohe Einkommen stärker belasten', '{4201}', 10762, 2, 2, null, 'Senkt die Belastung der Mehrheit der Beschäftigten und ist teilweise gegenfinanziert. Dagegen: keine dauerhafte Inflationsanpassung, Ausweichreaktionen hoher Einkommen mindern die Gegenfinanzierung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=11', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das gesamte Einkommensteuerreformgesetz 2027, mit höherem Reichensteuersatz gegenfinanziert, mindert die Einnahmen um rund 5,6 Mrd. Euro im Jahr 2028; nicht die Kosten dieses Wegs.","quelle_url":"https://dserver.bundestag.de/brd/2026/0507-26.pdf","belegstufe":"A"}]'::jsonb),
  (10805, 42, 16, null, 'Schuldenbremse abschaffen, damit öffentliche Investitionen über Kredite finanziert werden können', '{4202}', 10764, 1, 1, null, 'Kann Investitionsstau abbauen und Wachstum stützen; IWF verweist auf Investitionsverdrängung durch starre Regeln. Dagegen: erhöht Defizit und Zinslast unmittelbar; erfordert Grundgesetzänderung mit Zweidrittelmehrheit, EU-Regeln gelten weiter.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=13', 'https://www.imf.org/-/media/files/publications/sdn/2018/sdn1804-on-second-generation-fiscal-rules.pdf.md', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der Finanzplan sieht Zinsausgaben des Bundes von rund 41,9 Mrd. Euro 2027 und 80,7 Mrd. Euro 2030 vor; das sind nicht allein die Kosten dieses Wegs.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205072","belegstufe":"A"},{"bereich":"umwelt","richtung":"vorteil","text":"Zum Vergleich: Das Sondervermögen mit bis zu 500 Mrd. Euro Kredit führt dem Klima- und Transformationsfonds 100 Mrd. Euro zu; das sind nicht allein die Folgen dieses Wegs.","quelle_url":"https://dserver.bundestag.de/btd/21/007/2100779.pdf","belegstufe":"A"}]'::jsonb),
  (10806, 42, 16, null, 'Vermögensteuer wieder einführen (mit Freibetrag, progressiver Satz)', '{4203}', 10768, 2, 2, null, 'Erhöht den Anteil vermögensbezogener Steuern; DIW schätzt je nach Ausgestaltung zweistellige Milliardenbeträge. Dagegen: Ausweichreaktionen, Bewertungsaufwand und Verfassungsvorgaben zur Bewertung; Aufkommen fließt den Ländern zu.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=10', 'https://www.diw.de/de/diw_01.c.1002952.de/nachrichten/es_gibt_bessere_wege__vermoegen_zu_besteuern.html', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Das DIW schätzte 2016 für eine wieder erhobene Vermögensteuer auch bei hohen Freibeträgen ein Aufkommen von 10 bis 20 Mrd. Euro im Jahr.","quelle_url":"https://www.diw.de/de/diw_01.c.525353.de/publikationen/wochenberichte/2016_04/hohes_aufkommenspotential_bei_wiedererhebung_der_vermoegensteuer.html","belegstufe":"B"}]'::jsonb),
  (10807, 42, 16, null, 'Einmalige Vermögensabgabe für die Reichsten zur Finanzierung der Krisen- und Transformationskosten', '{4202}', null, 2, 1, null, 'Einmalige Vermögensabgabe kann hohe Einnahmen bringen und Kreditbedarf senken. Dagegen: Grundgesetz erlaubt sie nur bei außerordentlichem Finanzbedarf, Bewertung und Ausweichen schwierig, Aufkommen unsicher.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=11', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Zum Vergleich: Das DIW berechnete 2012 für eine Abgabe von 10 Prozent auf private Vermögen über 250.000 Euro rund 230 Mrd. Euro Aufkommen; das ist ein anderes Modell als dieser Weg.","quelle_url":"https://www.diw.de/de/diw_01.c.405753.de/vermoegensabgaben_-_ein_beitrag_zur_sanierung_der_staatsfinanzen_in_europa.html","belegstufe":"B"},{"bereich":"wirtschaft","richtung":"nachteil","text":"Eine Vermögensabgabe kann Betriebsvermögen erfassen; das DIW empfahl in einem Modell hohe Freibeträge, um Liquidität und Finanzierung kleinerer Unternehmen zu schützen.","quelle_url":"https://www.diw.de/de/diw_01.c.405753.de/vermoegensabgaben_-_ein_beitrag_zur_sanierung_der_staatsfinanzen_in_europa.html","belegstufe":"B"}]'::jsonb),
  (10808, 42, 16, null, 'Übergewinnsteuer von 90 Prozent auf Krisenprofite einführen', '{4202}', null, 1, 1, null, 'Kann in Krisen zusätzliche Einnahmen bringen. Dagegen: Abgrenzung von Krisengewinnen schwierig, 90 Prozent verfassungsrechtlich heikel, EU-Solidaritätsbeitrag 2022 brachte weniger als erwartet.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=12', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Zum Vergleich: Für den EU-Energiekrisenbeitrag (33 Prozent) schätzte die Bundesregierung 2022 und 2023 zusammen ein bis drei Mrd. Euro Mehreinnahmen; das sind nicht die Einnahmen dieses Wegs.","quelle_url":"https://www.bundesregierung.de/breg-de/aktuelles/eu-energiekrisenbeitrag-2145638","belegstufe":"A"}]'::jsonb),
  (10809, 42, 16, null, 'Steuerhinterziehung konsequent verfolgen, Strafverfolger und Finanzämter personell und technisch stärken', '{4202}', 10767, 2, 2, null, 'Betriebsprüfer erzielen im Schnitt rund 1 Mio. Euro Mehrergebnis je Jahr, mehr Personal erhöht die Einnahmen. Dagegen: Finanzämter sind Ländersache, Fachkräfte fehlen; der Bund kann nur über Gesetze, Bundesbehörden und Vereinbarungen beitragen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=13', 'https://www.zdfheute.de/wirtschaft/kampf-gegen-steuerhinterziehung-finanzamt-100.html', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Zum Vergleich: Betriebsprüfungen der Länder stellten 2023 steuerliche Mehrergebnisse von rund 13,2 Mrd. Euro fest; das sind nicht die Erträge zusätzlicher Prüfer.","quelle_url":"https://dserver.bundestag.de/btd/20/112/2011267.pdf","belegstufe":"A"}]'::jsonb),
  (10810, 42, 16, null, 'Finanztransaktionssteuer von 0,1 Prozent auf jede Finanztransaktion', '{4203}', 10771, 1, 2, null, 'Besteuert bisher steuerfreie Kapitaltransaktionen; Frankreich und Italien erheben sie. Dagegen: dortige Einnahmen blieben unter den Prognosen, Handel weicht aus; national einführbar, Bemessungsgrundlage strittig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=12', 'https://articlegateway.com/index.php/JAF/article/view/6562', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"wirtschaft","richtung":"gemischt","text":"Die Wissenschaftlichen Dienste verweisen auf Erfahrungen in Frankreich und Italien: Handelsvolumen kurz- bis mittelfristig 10 bis 30 Prozent niedriger, aber nur begrenzte Effekte auf die Liquidität.","quelle_url":"https://www.bundestag.de/resource/blob/1100514/WD-4-022-25.pdf","belegstufe":"B"}]'::jsonb),
  (10811, 42, 16, null, 'Grunderwerbsteuer so reformieren, dass Teilkäufe von Immobilien anteilig besteuert werden', '{4203}', null, 1, 3, null, 'Erschwert Share Deals und erhöht das Aufkommen einer vermögensbezogenen Steuer. Dagegen: seit 2021 bereits verschärft, Mehreinnahmen begrenzt und den Ländern zufließend.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=11', null, 'offen', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Vor der Verschärfung 2021 gingen Schätzungen davon aus, dass dem Staat durch Share Deals jährlich etwa 1 Mrd. Euro Grunderwerbsteuer entgeht.","quelle_url":"https://dserver.bundestag.de/btd/19/285/1928528.pdf","belegstufe":"A"}]'::jsonb),
  (10812, 42, 16, null, 'Grundsteuer am Verkehrswert ausrichten und nicht auf Mieter umlegen', '{4203}', null, 1, 2, null, 'Verkehrswertorientierung stärkt die Grundsteuer als vermögensbezogene Steuer, Umlageverbot verlagert Last auf Eigentümer. Dagegen: Reform eher aufkommensneutral, Länder haben Abweichungsrecht, Bewertung aufwendig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=10', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10813, 42, 17, null, 'Einkommen bis 7500 Euro brutto steuerlich entlasten', '{4201}', null, 1, 2, null, 'Senkt die Steuerlast für die große Mehrheit der Beschäftigten. Dagegen: Umfang und Tarifverlauf unbestimmt, keine dauerhafte Inflationsanpassung, Finanzierung offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=16', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Eine Anhebung des Grundfreibetrags um 216 Euro mindert die Steuereinnahmen laut Gesetzentwurf um rund 1,9 Mrd. Euro im Jahr; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dserver.bundestag.de/brd/2026/0507-26.pdf","belegstufe":"A"}]'::jsonb),
  (10814, 42, 17, null, 'Steuerlichen Grundfreibetrag deutlich erhöhen, orientiert an der Armutsgefährdungsschwelle', '{4201}', 10760, 2, 1, null, 'Entlastet alle Steuerpflichtigen spürbar und gleicht aufgelaufene kalte Progression mehr als aus. Dagegen: einmaliger Schritt ohne dauerhafte Anpassung und Ausfälle in zweistelliger Milliardenhöhe ohne geklärte Gegenfinanzierung.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', null, 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Eine Anhebung des Grundfreibetrags um 216 Euro mindert die Steuereinnahmen laut Gesetzentwurf um rund 1,9 Mrd. Euro im Jahr; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dserver.bundestag.de/brd/2026/0507-26.pdf","belegstufe":"A"}]'::jsonb),
  (10815, 42, 17, null, 'Spitzensteuersatz erst bei sehr hohen Einkommen ansetzen', '{4201}', 10761, 2, 1, null, 'Mildert den steilen Progressionsverlauf bei mittleren Einkommen, an dem die kalte Progression besonders wirkt. Dagegen: einmalige Änderung ohne Indexierung, Entlastung absolut v. a. bei höheren Einkommen, hohe Ausfälle ohne Finanzierung.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', null, 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das gesamte Einkommensteuerreformgesetz 2027 mindert die Steuereinnahmen um rund 5,6 Mrd. Euro im Jahr 2028; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://dserver.bundestag.de/brd/2026/0507-26.pdf","belegstufe":"A"}]'::jsonb),
  (10816, 42, 17, null, 'Vermögensteuer ab 25 Mio. Euro Vermögen mit 1 bis 3 Prozent wieder einführen', '{4203}', 10768, 2, 2, null, 'Erhöht den Anteil vermögensbezogener Steuern; DIW schätzt je nach Ausgestaltung zweistellige Milliardenbeträge. Dagegen: Ausweichreaktionen, Bewertungsaufwand und Verfassungsvorgaben zur Bewertung; Aufkommen fließt den Ländern zu.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', 'https://www.diw.de/de/diw_01.c.1002952.de/nachrichten/es_gibt_bessere_wege__vermoegen_zu_besteuern.html', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Das DIW schätzte 2016 für eine wieder erhobene Vermögensteuer auch bei hohen Freibeträgen ein Aufkommen von 10 bis 20 Mrd. Euro im Jahr.","quelle_url":"https://www.diw.de/de/diw_01.c.525353.de/publikationen/wochenberichte/2016_04/hohes_aufkommenspotential_bei_wiedererhebung_der_vermoegensteuer.html","belegstufe":"B"}]'::jsonb),
  (10817, 42, 17, null, 'Vererbte Vermögen oberhalb der Freibeträge gleich besteuern', '{4203}', 10769, 2, 3, null, 'Große Betriebsvermögen werden weitgehend steuerfrei übertragen, Schätzungen nennen Ausfälle in Milliardenhöhe; Stundung kann Liquiditätsprobleme mildern. Dagegen: Unternehmensverbände warnen vor Investitionsfolgen, Ausweichgestaltungen möglich.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2016/heft/6/beitrag/die-demontage-der-erbschaftsteuer.html', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"vorteil","text":"Bei großen Betriebsvermögen wurden 2025 im Rahmen der Verschonungsbedarfsprüfung Steuern von 3,7 Mrd. Euro erlassen; eine Begrenzung der Verschonung betrifft solche Beträge.","quelle_url":"https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/08/PD26_306_736.html","belegstufe":"A"}]'::jsonb),
  (10818, 42, 17, null, 'Finanztransaktionssteuer auf Wertpapier- und Derivategeschäfte einführen', '{4203}', 10771, 1, 2, null, 'Besteuert bisher steuerfreie Kapitaltransaktionen; Frankreich und Italien erheben sie. Dagegen: dortige Einnahmen blieben unter den Prognosen, Handel weicht aus; national einführbar, Bemessungsgrundlage strittig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', 'https://articlegateway.com/index.php/JAF/article/view/6562', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"wirtschaft","richtung":"gemischt","text":"Die Wissenschaftlichen Dienste verweisen auf Erfahrungen in Frankreich und Italien: Handelsvolumen kurz- bis mittelfristig 10 bis 30 Prozent niedriger, aber nur begrenzte Effekte auf die Liquidität.","quelle_url":"https://www.bundestag.de/resource/blob/1100514/WD-4-022-25.pdf","belegstufe":"B"}]'::jsonb),
  (10819, 42, 17, null, 'Familien beim ersten selbstgenutzten Eigenheim von der Grunderwerbsteuer befreien', '{4203}', null, 0, 2, null, 'Entlastet Ersterwerber laut IW deutlich, senkt aber das Aufkommen einer vermögensbezogenen Steuer und verstärkt so das Gewicht von Lohn- und Umsatzsteuer. Aufkommen und Satzhoheit liegen bei den Ländern, Ausgleich nötig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', 'https://www.iwkoeln.de/studien/gutachten/beitrag/tobias-hentze-bjoern-seipelt-michael-voigtlaender-reform-der-grunderwerbsteuer-325128.html', 'belegt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das Aufkommen der Grunderwerbsteuer, die den Ländern zusteht, betrug 2024 rund 12,7 Mrd. Euro; das sind nicht die Kosten dieses Wegs.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1050734","belegstufe":"A"}]'::jsonb),
  (10820, 42, 17, null, 'Belastungsmoratorium bei der Grundsteuer für Eigenheimbesitzer und Mieter', '{4203}', null, 0, 1, null, 'Bremst Mehrbelastungen bei der Grundsteuer, senkt aber das Aufkommen einer vermögensbezogenen Steuer. Hebesätze legen Kommunen fest, Länder haben Abweichungsrecht; der Bund kann kaum allein handeln.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', null, 'offen', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die Gemeinden nahmen 2024 aus der Grundsteuer B 15,6 Mrd. Euro ein; das sind nicht die Mindereinnahmen dieses Wegs.","quelle_url":"https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/08/PD25_309_713.html","belegstufe":"A"}]'::jsonb),
  (10821, 42, 17, null, 'Investitionen in Infrastruktur aus der Schuldenbremse ausklammern', '{4202}', 10764, 1, 1, null, 'Kann Investitionsstau abbauen und Wachstum stützen; IWF verweist auf Investitionsverdrängung durch starre Regeln. Dagegen: erhöht Defizit und Zinslast unmittelbar; erfordert Grundgesetzänderung mit Zweidrittelmehrheit, EU-Regeln gelten weiter.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=15', 'https://www.imf.org/-/media/files/publications/sdn/2018/sdn1804-on-second-generation-fiscal-rules.pdf.md', 'gemischt', '2026-10-22', false, true, 'blind', '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der Finanzplan sieht Zinsausgaben des Bundes von rund 41,9 Mrd. Euro 2027 und 80,7 Mrd. Euro 2030 vor; das sind nicht allein die Kosten dieses Wegs.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205072","belegstufe":"A"},{"bereich":"umwelt","richtung":"vorteil","text":"Zum Vergleich: Das Sondervermögen mit bis zu 500 Mrd. Euro Kredit führt dem Klima- und Transformationsfonds 100 Mrd. Euro zu; das sind nicht allein die Folgen dieses Wegs.","quelle_url":"https://dserver.bundestag.de/btd/21/007/2100779.pdf","belegstufe":"A"}]'::jsonb),
  (10822, 42, 17, null, 'Teure Beraterverträge im Militärbereich beenden, volle Transparenz über Militärausgaben', '{4202}', null, 1, 3, null, 'Weniger externe Berater und mehr Transparenz können Ausgaben senken. Dagegen: Einsparvolumen gemessen am Defizit gering, eigenes Fachpersonal muss teils erst aufgebaut werden.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=6', null, 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10823, 42, 17, null, 'Rüstungsindustrie zur Haftung für Kostensteigerungen und Verzögerungen verpflichten', '{4202}', null, 1, 2, null, 'Bundesrechnungshof: wegen schwacher Verträge konnte die Bundeswehr Mehrkosten nicht dem Auftragnehmer anlasten. Dagegen: Hersteller preisen Risiken ein, wenige Anbieter, Wirkung erst bei neuen Verträgen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=6', 'https://vergabeblog.de/2018-04-25/bundesrechnungshof-ruegt-unwirtschaftliches-verhalten-in-den-bereichen-gesundheit-steuern-bundeswehr-und-strassenbau/', 'offen', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10824, 42, 17, null, 'Verwaltung soll Open-Source-Lösungen statt teurer Software-Rahmenverträge einsetzen', '{4202}', null, 1, 2, null, 'Kann Lizenzkosten senken; München meldete Einsparungen in Millionenhöhe. Dagegen: Umstellung kostet zunächst, München kehrte zu Windows zurück, Einsparungen gemessen am Bundesdefizit gering.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=43', 'https://www.computerworld.com/article/1398642/switch-to-open-source-successfully-completed-city-of-munich-says.html', 'gemischt', '2026-10-22', false, true, 'blind', '[]'::jsonb),
  (10961, 42, 13, null, 'Grundfreibetrag der Einkommensteuer erhöhen (ohne Betrag).', '{4201}', null, 1, 3, null, 'Ein höherer Grundfreibetrag entlastet alle Steuerpflichtigen und gleicht einen Teil der kalten Progression aus. Dagegen: einmaliger Schritt ohne Betrag und ohne dauerhafte Anpassung. Nachgetragen in Anlehnung an die gleichartige, blind bewertete Zusage (Grundfreibetrag um 1.000 Euro anheben).', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=74', null, 'offen', '2026-10-23', false, true, 'nicht_blind', null);

